FUNCTION @@proc@@ (p_a IN VARCHAR2, p_b IN VARCHAR2, p_c IN VARCHAR2, p_d IN VARCHAR2) RETURN VARCHAR2 IS
    l_out VARCHAR2(400);
BEGIN
    l_out := p_a;
    l_out := l_out || ', ' || p_b; -- @expect
    l_out := l_out || ', ' || p_c; -- @expect
    l_out := l_out || ', ' || p_d; -- @expect
    RETURN l_out;
END @@proc@@;

FUNCTION @@proc@@ (p_n IN NUMBER) RETURN NUMBER IS
    l_acc NUMBER := 0;
BEGIN
    FOR i IN 1..@@num@@ LOOP -- @expect
        l_acc := l_acc + MOD(i, @@num@@); -- @expect
    END LOOP;
    IF p_n > @@num@@ THEN -- @expect
        l_acc := l_acc / 2;
    END IF;
    RETURN l_acc;
END @@proc@@;

FUNCTION @@proc@@ (p_a IN VARCHAR2, p_b IN VARCHAR2, p_c IN VARCHAR2) RETURN NUMBER IS
    l_total NUMBER;
BEGIN
    -- count how many flags are set
    l_total := CASE WHEN p_a = 'Y' THEN 1 ELSE 0 END -- @expect
             + CASE WHEN p_b = 'Y' THEN 1 ELSE 0 END -- @expect
             + CASE WHEN p_c = 'Y' THEN 1 ELSE 0 END; -- @expect
    @@proc2@@(l_total);
    RETURN l_total;
END @@proc@@;

PROCEDURE @@proc@@ (p_val IN NUMBER, p_out OUT NUMBER) IS
    PROCEDURE helper IS
    BEGIN
        NULL;
    END helper;
BEGIN
    helper;
    BEGIN
        p_out := p_val * @@num@@; -- @expect
    EXCEPTION
        WHEN VALUE_ERROR THEN
            p_out := @@num@@; -- @expect
    END;
    IF p_out > @@num@@ THEN -- @expect
        p_out := 0;
    END IF;
END @@proc@@;

