FUNCTION @@proc@@ (p_a IN VARCHAR2, p_b IN VARCHAR2, p_c IN VARCHAR2) RETURN VARCHAR2 IS
    l_out VARCHAR2(400);
BEGIN
    l_out := p_a || ';' || p_b || ';' || p_c || ';';
    l_out := l_out || '%' || '%' || ' ' || ' ' || ' ';
    IF l_out = '' OR l_out IS NULL THEN
        l_out := '';
    END IF;
    RETURN SUBSTR(l_out, 1, 0 + 1) || '' || TO_CHAR(0 + 1);
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN NUMBER, p_out OUT VARCHAR2) IS
BEGIN
    -- the limit @@num@@ is documented as @@num@@ elsewhere
    IF p_n > @@num@@ THEN
        p_out := '@@str@@';
    ELSIF p_n < @@num@@ THEN
        p_out := '@@str@@';
    ELSE
        p_out := 'prefix_@@str@@';
    END IF;
    /* @@num@@ */
    p_out := p_out || ' (@@num@@)';
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN NUMBER, p_s IN VARCHAR2, p_out OUT NUMBER) IS
BEGIN
    p_out := p_n + @@num@@;
    IF p_s = '@@num@@' THEN
        p_out := p_out * @@num@@;
    ELSIF p_s = '@@num@@' THEN
        p_out := 0;
    END IF;
    @@proc2@@(p_out);
END @@proc@@;

FUNCTION @@proc@@ (p_state IN VARCHAR2) RETURN NUMBER IS
BEGIN
    -- state '@@str@@' is the terminal one; '@@str@@' is never reused below
    IF p_state = '@@str@@' THEN
        RETURN 2;
    ELSIF p_state = '@@str@@' THEN /* '@@str@@' again in a block comment */
        RETURN 3;
    END IF;
    RETURN 0;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_val IN NUMBER) IS
    l_rows PLS_INTEGER;
BEGIN
    UPDATE @@tab@@ SET "STATUS" = p_val WHERE id = p_id;
    l_rows := SQL%ROWCOUNT;
    UPDATE @@tab2@@ SET "STATUS" = p_val WHERE id = p_id;
    l_rows := l_rows + SQL%ROWCOUNT;
    DELETE FROM @@tab@@ WHERE "STATUS" IS NULL;
    @@proc2@@(l_rows);
END @@proc@@;
